class _FFTrainAsBangla(dict):
    """FF dev-exclusion (CHANGES.md #5): flag_extract.extract_ssl runs its fp16-vs-fp32 self-check on 4 clips of
    S["no_gender/Bangla"] (a dev list) before it encodes every split of S. Only "train" is indexed here, so that one lookup
    is answered with the train list; items() still yields the train list alone, so only voice_<ssl>_train.npy is written,
    as in the original run (voice_wavlm_train / voice_xlsr_train, (6485, 25, 1024))."""
    def __missing__(self, k):
        if k == "no_gender/Bangla":
            return self["train"]
        raise KeyError(k)


for model_id, short in SSL:
    try:
        SSL_COS[short] = X.extract_ssl(_FFTrainAsBangla(S), OUT, model_id, short)
